) AS (
  VALUES 
    (129::BIGINT, 'Demasiado egocentrico, pone trabajos tan largos como si la materia fuera la mas importante del mundo. No para de intentar demostrar su superioridad "intelectual" frente a los estudiantes y humilla a los que no son chupa medias'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2026-09-23T00:00:00+00:00'::TIMESTAMPTZ, '72be48e4502d7e918bafe492ce25bf00d0728436eb28cd429533dffb07fbbc7d'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Es lo peor que podrían escoger, el profesor si la agarra contra uno prepárese para sufrir. Hace el curso tan complicado y sin sentido, no lo recomiendo para nada. Esos ejemplos que tira en las clases es mejor que se los guarde porque no sirven paran nada.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-09-22T00:00:00+00:00'::TIMESTAMPTZ, '392772bfd98609e058be649e6451252f6be05ea59365408c19f583e971ebdd15'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Si tiene un mínimo de aprecio a su salud mental, no matricule con este tipo e ignore los únicos comentarios positivos que tiene aquí, siempre son de él mismo o de los chupamedias extremos. No es más que un chancletudo frustrado que nadie le da pelota, y para compensarlo se autoengrandece en el aula.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2026-07-15T00:00:00+00:00'::TIMESTAMPTZ, '4eba48dda9959df5075d022040a538bc90c0a5a41e7f9d93fd26cffddbdbdd98'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Un claro ejemplo de lo que es un ser que se enorgullece de su arrogancia y egocentrismo. Cree que sus creencias están por encima de los demás, es sarcástico al responder preguntas simples y parece que la educación es un simple chiste para él, si puede nunca matricule con este profesor tan mediocre.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-05-12T00:00:00+00:00'::TIMESTAMPTZ, '3dd04a70357c5556ce62f8a2994e5698738552cd1e0a47b9b896ca921b3c72ab'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Es una persona que siempre tiene la razón. Cree que puede desviar el curso al tipo de vida o creencias que tiene. Se burla de estudiantes por ser religiosos. Responde de manera soez y trata a los estudiantes como tontos. Definitivamente se cree el mejor ser humano del planeta.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2026-05-11T00:00:00+00:00'::TIMESTAMPTZ, 'f1e245b8734e2c49842a9c681488f3e01c8d2f00b1107bf52d8bd5e2e9901512'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'La personificación de egocéntrico y narcisista. Trata a los estudiantes y otros funcionario de ignorantes si no concuerdan con sus opiniones.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-03-26T00:00:00+00:00'::TIMESTAMPTZ, '00a65c4fc720e37b5159cc3458174b123c5f673350130cbbc97767377b7e5dd3'::TEXT, ARRAY[2460]::BIGINT[]),
    (129::BIGINT, 'Trata a su como si valiera 6 creditos y solo vale 2 creditos. Es 0 accesible se cree la ultima coca en el desierto. Es super egocentrico. Critica las preguntas, y responde mal o inadecuadamente a unas preguntas sin maldad. Trata mal a los estudiantes. Toma asistencia sacando captura de pantalla.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2026-03-14T00:00:00+00:00'::TIMESTAMPTZ, '27fdd6c401031a27eaacd2b1687a33f510aa375c4e63c920e06c439030d2ab9c'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-03-14T00:00:00+00:00'::TIMESTAMPTZ, 'b67f0c9cf10438d5a3fbd80e541adf481a65ead05aa05eb33270b89d080c2ec9'::TEXT, ARRAY[2460]::BIGINT[]),
    (129::BIGINT, 'Es un profesor horrible, no tenemos ni un mes y nadie lo soporta, se cree muy inteligente y denigra a los demás, habla de temas que no van con la materia, temas muy ofensivos; trata su materia de 2 créditos como si valiera 6, no lo recomiendo en lo absoluto, jamás volvería a matricular con él'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-03-07T00:00:00+00:00'::TIMESTAMPTZ, 'b8e19d5fde85d48e74044534b10c7762c71d7e24a213ffedfdf705b3c4acfb68'::TEXT, ARRAY[2460]::BIGINT[]),
    (129::BIGINT, 'Háganse un favor y ni se les pase por la mente matricular, es un profesor prepotente, exótico, juega de vivo y si usted no esta de acuerdo con el mamo, se cree superior el muy playo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-03-04T00:00:00+00:00'::TIMESTAMPTZ, 'a38634c44111476d257f8665a804b022606acf96062346b97255f3ab0c482aad'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Le gusta humillar estudiantes, no se le pueden acercar con dudas, cronograma confuso, cambios de ideas, le gusta imponer sus ideas. El peor profesor que he conocido en el tec por mucho'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'f271fb24567c0a03ddbcbb4611fa450d4e1d7d3385c319f2d9f4c2f7ba9b38e4'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Es un excelente profesor, de los mejores que he tenido. Si usted es una persona RESPONSABLE con un interés geniuno en aprender y esforzarse, va a disfrutar mucho el curso y sus clases en general. Si usted es una persona mediocre que quiere hacer todo con chat gpt, ni siquiera lo considere.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases excelentes']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '7be01d53c5564a53ec42386c457cd9bac750fd92ac20190aee8836b500ebd9a0'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'El profesor necesita urgentemente una capacitación sobre el uso de la plataforma TEC Digital, la inflexibilidad del profesor, su incapacidad de responder preguntas de forma concisa, la constante comparación verbal entre grupos y estudiantes, incapacidad de aceptar sus errores, dificultaron el curso.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'b24b8f7347d263b9992b6fdaed97a03c7664bedc1039072f8d7d710b5a211b5f'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Califica como se le da la gana. Es muy buen profe para los chupamedias y mujeres. Los trabajos son grupales y depende de su grupo el curso se puede volver muy pesado. Curso de 4 cred cuando es de 2. No lo lleve con materias importantes porque quita mucho tiempo.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'c9a0ac9f9a63aa22e2f4f0adec31e6e78b7ea80be5a8ee37db74f561fa18cca7'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Suele ser muy cuadrado respecto a cómo manifestar interés en la clase, el plan y la clase no tienen casi nada que ver como tal y se vuelve redundante en las últimas semanas. Curso de 3-4 créditos para ser de 2.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '99f175efb552df647dad7d86a30e500deaabac3cdcf8e4584b8b986f7c21eb73'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Se cree interesante, pero solo es un chancletudo más. El ego es muy alto para la falta de conocimiento que tiene. Si a alguien le va bien es porque adula al inútil.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '1ccc4a14c11dfa2545ddf4f15245b9ab6035d6e4581400a89e798f29060be9a1'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Califica como le de la gana, se cree intelectual pero solo es un chancletudo más.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2024-03-12T00:00:00+00:00'::TIMESTAMPTZ, '036d61394a0a7b04ffd553a0a921b7e000016641c7738d37cc78c0c1ca381d86'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'El profe tiene mucho conocimiento en la materia; sin embargo, como profe no es el mejor. La mayoría de la clase pasa hablando sobre él y todos los títulos que tiene. Cada vez que puede, menciona que es ateo y vegano. Es muy sarcástico y tiende a humillar algunas veces. (el curso lo llevé en verano)'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Da crédito extra']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'c92327431e37e9bb84fd970a9e07037304996914fd964da79cd3e858d2331897'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Un profesor prepotente que en vez de ayudar aprovecha cada oportunidad para humillar a sus estudiantes y explicar porqué el es moralmente superior. Aunque sea el último profesor disponible no matriculen con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2023-11-29T00:00:00+00:00'::TIMESTAMPTZ, '44390224c2ebce5517f256d41066246a37d4de873cd42ea0b8361809e73f1b8f'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es un profesor engreído y prepotente, su actitud frente a las consultas es pésima y brinda poca ayuda. Tiende a calificar por criterio propio y favorece a estudiantes que le caigan bien.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Clases largas']::TEXT[], '2023-10-21T00:00:00+00:00'::TIMESTAMPTZ, 'f3b5130e7f0e7159b9af24c6c921e8860d230221a10aab6dce3252fa9735b8ba'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'No matriculen con él si pueden. Habla cosas importantes pero le encanta rajar y dejar toda la tarea que pueda como si uno no tuviera nada más que hacer.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-09-13T00:00:00+00:00'::TIMESTAMPTZ, '7d60c555fb0d6d5bcb761038913a2a88e9818e5572956439a679732dca1d059c'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Hace que el curso se sienta como de 4 créditos con un montón de trabajos tediosos que califica sin rubricas, él piensa que los estudiantes son vagos cuando él lo único que hace clases es criticar, su actitud hacia las consultas es pésima y trata de humillar a los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Deja trabajos largos']::TEXT[], '2023-08-30T00:00:00+00:00'::TIMESTAMPTZ, '695d340a13c4ce78e685e7f45bb5baa4888c802c3baaf7691a8bc54c20e792b2'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'No da ninguna clase útil respecto al tema del curso, siempre cree tener la razón y se burla de los estudiantes que le hacen consultas, aunque él tenga errores nunca lo reconoce y prefiere humillar al estudiante. Sus aspectos de calificación siempre son a criterio personal y no por una rubrica.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2023-08-19T00:00:00+00:00'::TIMESTAMPTZ, '7ac85e28c8eb7a9c4ac2ecc209b00a633b9e7d18445ab8c91deb96406c26f796'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Las respuestas a las consultas tienden a ser ambiguas. Siempre cree tener la razón y busca dejarlo a uno en mal cuando le cuestionan algo. La retroalimentación la hace en forma burlesca frente a los demás. Cree que sus calificaciones negativas son debido a "estudiantes mediocres" y no a su actitud.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-07-04T00:00:00+00:00'::TIMESTAMPTZ, '772116657bd170aab921df86660351e3d859bc0831ad1de978dc2875e2ad6a61'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Si tiene algo de amor propio en su ser, hágase un favor y no matricule con semejante personaje, es un tipo sumamente egocéntrico e insoportable, piénselo dos veces antes de matricular con este ser.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, '72d0b3041b12e45f73fa84c4a5266759afeae15143ee84c9c5592f83cbc83318'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Demasiada gente lo odia, es cierto que habla mucho de él y eso puede chocar, pero si a usted eso le vale es muy buen profe. Se aprende bastante, como profesional es excelente, no hace el curso pesado, si ocupa algo y habla con él sí ayuda y es comprensivo, participe bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '687eacca93dd0f1eaa549f9c3871f558602e3796660951db7c9de38ba39c5512'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es pésimo profesor, su actitud pedante y egocéntrica hacen poco disfrutable la clase, los aspectos con los que califica son poco claros y se basan solo en su criterio.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'f89383d5e586b1460758eb9f04f4f15d2e4c07cd2bae97fcb5b37fc418db116c'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Gran conocimiento de la materia, sin embargo el profesor se encarga de que el estudiante se aprenda todas las maestrías y doctorados que él tiene, mala actitud, espera que todos sus estudiantes se dediquen de lleno a su materia.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '5945cd0e99b45f81cb1e78f875b34250e4b7f6c96b8c1993cfc6659ca5e3bb93'::TEXT, ARRAY[559]::BIGINT[]),
    (129::BIGINT, 'Es un engreído que busca la amistad con algunos estudiantes a los que beneficia para ver si recibe una buena reseña.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'a5701cd3f56fca883a91dfc6f999a5efd84381729d625a8fb0f2ba8eae75f122'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Búsquese un buen grupo desde el principio porque evalúa de manera grupal (la nota de los demás te afecta). Tiene mucho conocimiento sobre varios temas y autores, lo cual hace las clases interesantes. Fomenta el pensamiento crítico en los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2023-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'bfc8ca6a21f1114aeb366dea004cc657612223e3a8928ca80a1567a65b859206'::TEXT, ARRAY[559]::BIGINT[]),
    (129::BIGINT, 'No se dejen llevar por los malos comentarios que le hacen al profe Wilmer. Delen la oportunidad de conocerlo, es un profe ejemplar demasiado comprometido con la docencia, busca sacar lo mejor de los estudiantes. Sí, a el le gusta la participación, así que saque su sapo/sapa interior. Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2023-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'f4ab77407e44c3293b0cfc117dfefc78fd6779747e893fb2146caa4530b71744'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Egocéntrico con una mentalidad pobre, se cree superior hablando de temas de los cuales el no tiene conocimiento, lo único de lo habla con propiedad es de su aburrida vida.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2023-05-27T00:00:00+00:00'::TIMESTAMPTZ, '3321134a85fae65c52e141c43eb579de278a00708d1087a59345f24ed5c7024e'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'El ambiente de la clase se ve afectado por una figura autoritaria y egocéntrica que constantemente resalta las calificaciones negativas de los trabajos. Las instrucciones de evaluación son deficientes o inexistentes. Y califica como se le da la gana y no existe reclamo alguno que se pueda hacer.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-05-20T00:00:00+00:00'::TIMESTAMPTZ, '8a38a8e0e39abdf51e1fe1df346238aa81205f31744cbf0a2a39ed8e07584aa5'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Ser profesor es algo que le queda grande, no sabe explicar y califica segun criterios propios, pero el ser un engreído y prepotente que humilla a los estudiantes se le da muy bien.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchas tareas']::TEXT[], '2023-05-01T00:00:00+00:00'::TIMESTAMPTZ, 'ab6157d28eba6029687e92209462f54c8b4895304d4e51d545b79016d99d91ec'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Muy intenso en clases con el tema de la participación. Siempre pone de ejemplo a las compañeras en temas que personalmente me tenían incómodo. Se aseguraba que aquellos que no hablan tanto la pasasen mal, señalándolos, lo cual no hacía más fácil que participáramos. Es demasiado egocéntrico.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-03-18T00:00:00+00:00'::TIMESTAMPTZ, 'd2b1e680d1e6bcf4d5bed297ffa4ac17e3c062fed4529d3660a0fa81ced5ddd2'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'El profe es muy intenso, esto puede ser malo o bueno. Le gusta que la gente participe, como tal no es obligatorio pero si no participan da un sermón al respecto. El profe siempre califica bien, da muy buena retroalimentación, y solo lo reprueba si de verdad no hace nada.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2023-01-20T00:00:00+00:00'::TIMESTAMPTZ, '77362bbd89b53afda75618c5026ca745a589bc4b778159673d7bf4193d269f0e'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Este hombre es horrible como profe, ir a una clase de él, es eso, ir a una clase de escucharlo hablar de él mismo, es super narcisista, si usted no le lee la mente le baja puntos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2023-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'e7afd65a922ea3e0ac180cc9fccd8b96a16c708e14bb9ee2fa7da2c62fc8a9ce'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es la peor pesadilla de cualquiera, es una persona tan insoportable que da depresión ir a esas clases, si se valora nunca meta con semejante persona tan prepotente y poco humana, con aires de superioridad, el mae se cree lo mejor del mundo. Un semi Dios ????'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '327c13217711685eb6faff51471026f932aa44eaf72a7522cd218ac6befabafe'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Nunca matricule con él, los estudiantes del TEC ya estamos lo suficientemente estresados para ir a gastar tres horas de nuestro tiempo escuchando una clase sobre el ego de este "hombre" y los resentimientos que tiene hacia la institución, además recibir retroalimentaciones humillantes y ofensivas.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, '6bb7d08db28c89d3d78d7b50be3a0a54e8afb4355d52994dd525d3f541739c8b'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Si me dijeran que tengo que llevar 50 cursos con Dimitri Shiltagh o llevar otro curso con Casasola preferiría llevar esos 50 cursos con Dimitri. Súper narcisista si usted no hace lo que él quiere es curso perdido. No lleven ningún curso con el, no va a cambiar en el siguiente semestre.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2022-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'daed06b42b7c78c8d7d8f59ab4800f2ffd3c37e5caf0c6cac8ea8813743f6858'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Sólo le voy a decir que nunca matricule con este mae, aunque sea la única opción no se lo recomiendo para nada. HUYA!!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2022-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'e840e6529de76081180757f7127f12d9b9035271a5b4501097cd424cc4303b7a'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'La gente habla muy mal de él, pero realmente es un profe bastante bueno, es sacarle el provecho para usted mismo, si es responsable y busca ayuda el le brindará todo lo que necesita además la metodología que usa es muy clara, te impulsa a ser un estudiante calidad TEC.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-15T00:00:00+00:00'::TIMESTAMPTZ, '25cff3860b4bfaca401520a5561367af26c2cc572fa5fec316d2e1b6784284ee'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Sus clases se tratan de él y de su ego. Pedante, egolatra, narsisista y simplemente no es capaz de escuchar un comentario que no alabe sus opiniones o investigaciones. Siempre recordandole que el es un ser que está sobre la media y que tiene un gran compromizo con la "ética".'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'e432f6109bc59d6ec64f5ac5dcb0a28e73dbd348dabf603ee946c902b8ab0d3c'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Evítelo a toda costa, es un tipo sumamente pedante y egocéntrico, la mitad de la clase es él hablando de sus 10 doctorados y expresando su desprecio que tiene hacia el TEC, te quita todo el interés de aprender, podrá ser un gran investigador, pero es un terrible como profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-10-31T00:00:00+00:00'::TIMESTAMPTZ, '74baff8eb799ab15b82a932df3409140036537554f18ee8a621636c53fef1351'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'No lo recomeindo para nadie, si aprecia su salud mental no matricule con el . El profe tiene un ideal del estudiante perfecto que el quiere en sus clases y nadie va a lograr cumplir sus expectativas. Él califica super duro pero dice que no es culpa de él sino de los estudiantes que no le ponene.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2022-10-18T00:00:00+00:00'::TIMESTAMPTZ, '122811db4e80f179987178a46c80c5618474431d60d0588277420fe626801100'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Personalidad pedante combinada con complejo de superioridad y neoliberalismo, siempre lo va a intentar aplastar por tener alguna opinión/ideología que no concuerde con las suyas, pésimo profe, de verdad nunca matricule con él a menos que quiera que le recuerden que usted es malo por no ser vegano.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-09-20T00:00:00+00:00'::TIMESTAMPTZ, '6b7b1546203456de42851b7e762932f14f75afe385a7bc0fe66d2107375dc53e'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Es una mierda de profesor, no matricule con este profesor. Tiene una actitud pedante y es muy repugnante. Habla solo de él, en clases virtuales la clase no tenía mucho que ver con las lecturas y siempre terminaba con algo nad que ver.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9d573eba079b807b03b4314f1ef8a5da00273e44d1df089a2bc8e6d90cebbac8'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'El profe no es malo, se ve que sabe mucho. El problema es que su personalidad puede llegar a ser muy chocante para muchos estudiantes, además de que siempre se burla de los estudiantes del Tec solo porque no le contestan cuando el quiere.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, '704a4fd87f4c5bf9dee1a4b2c5d71546841ce200152a9f95a53425c027fd7753'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'solo habla de él, de sus doctorados, de sus estudios y como no puede ser catedratico, tiene actitudes y comentarios machistas y misogenos. Le duele lo que comentan en esta página y dice que los estudiantes del TEC son pésimos, esta resentido porque el TEC no le paga sus "super investigaciones"'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2022-06-01T00:00:00+00:00'::TIMESTAMPTZ, '2d956d52a4791df37e9adc36dac44e3b397cd46f0349323c2d298da2c4d6f3d7'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-03-16T00:00:00+00:00'::TIMESTAMPTZ, 'fb3f23d8c2fd723ffc2950e04ae11a72a3e6aab37cc97d5ba2867bec4c8bb460'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'a2e1471bc6e3769e034f56fcfa6f2d67c27b19e54ef8e7780e06e2810ee2ee48'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Pedazo de mierda'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-09T00:00:00+00:00'::TIMESTAMPTZ, '80d5697a0335780f21541e8a870052183aeb3aee212ba384de2d2f5ebce4db13'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Así reacciona cuando le mencionas que las rubricas que entrega son erroneas: "No obstante no me sorprende su comentario. Como usted, hay muchos estudiantes. DIchosamente, no son la mayoría. Como le dije, para ese trabajo en específico, se les da 100." La actitud arrogante del profesor perfecto.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchas tareas']::TEXT[], '2022-01-07T00:00:00+00:00'::TIMESTAMPTZ, '43f2e1909f60d64e067f46ddaae17b6309b4375854f8e9e7776b7ba89e9cbc99'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Califica sin utilizar las rubricas, no explica los trabajos, tiene una actitud un poco sospechosa con las estudiantes mujeres, es pedante y arrogante. Sinceramente no matriculen con él, hay mejores maneras de desperdiciar el tiempo y el dinero.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-11-12T00:00:00+00:00'::TIMESTAMPTZ, '30543cf6fded7b635b7a563497a5ff4d834b9e24ac433a0abb706906a8611029'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Trata de ser un profesor super estricto pero en realidad es un ateo que solo habla de el y los estudiantes para el no valen nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-09-07T00:00:00+00:00'::TIMESTAMPTZ, 'ec80acc6d51281c5b169f72f9ae11f65ae55ac185d880f825d5240119b8f7148'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Es malo y un profesor que no brinda apoyo cuando se le pide'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-08-27T00:00:00+00:00'::TIMESTAMPTZ, '52a44303bc0e9c46a8811607211453fbc48fa8c5a1fa72589978d8b0827416fa'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Es un profesor que califica muy duro y según sus opiniones, si algún trabajo no le gusta va a humillar a los estudiantes que hicieron el trabajo refiriéndose a que los estudiantes son completamente mediocres y no merecen estar en TEC, en las clases se aprende muy poco ya que sólo habla de él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchas tareas']::TEXT[], '2021-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'a32872ff0deeee35b3d8c37fc2b641a24b32fc8c02f53b9759af706e38362b84'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Un profesor que se concentra en la excelencia académica y que uno analice , pero pone eso como excusa a su actitud pedante y conflictiva. Termine perdiendo todo el interés en la clase'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '90357abaffa3740b042b029acf244b23ec6e20d0d13283ca6cea2a1e1e8dac16'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'El profe es grosero,trata mal a los estudiantes,si uno le pregunta algo referente a un trabajo te trata mal, deja demasiadas lecturas y trabajos, en general mientras usted los entregue bien hechos va a pasar con buena nota, pero estos trabajos son grandes y requieren mucho tiempo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '67d40013b9cac49be5d9ca8687d6855490424d9d036ad67d4f926ba0bed0da1d'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Pésimo profesor es un pedante, arrogante, 0 humilde, irrespectuoso hacia el estudiante, se cree superior por ser ateo, el estudiante siempre es el malo se saca rubricas de la nada, la verdad es mejor por su salud mental, evitar tratar con este tipo de personas'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'fc9f6eac25dbcee160c7ed6bb9716d40c0db3e11b560d11deaff3573702d646a'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Diferencia en la cantidad de integrantes de los grupos de trabajo. Para el proyecto hay grupos de 2 estudiantes y otros de 5 para el mismo trabajo lo peor es que él hace los grupos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2021-03-20T00:00:00+00:00'::TIMESTAMPTZ, '50a3488cde8cec8a4730e5712db7333502491b08d5c2e7bbdbe41dfba3c4fc9e'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es fácil pasar si se hace todo lo del curso, sin embargo esto no es todo lo que hay que considerar en un profesor. Trata un curso de 2 créditos como si fuera de 4, se pasa quejando en las clases de la calificación que mantiene en esta página. No recomendado.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '7526a9b3122ec0464c899d3ee94e4aa3cbf94425596312b1f4ceacf13b6c8a11'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Psudointelectual extremadamente arrogante. Empatía inexistente y emocionalmente depravado. Lo único positivo es que lee las reseñas en esta página y le duele, lo malo es que solo de eso habla en clase. Si no hay otro profe, mejor no matriculen. Un dolor para las revisiones. Muy injusto. Malcriado.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'd440b4f40a2a4d6d6b567aa55cb20581b960b33baf5d35b35aca429a782ce6a0'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'El curso que vale 2 créditos parecía de 10, pide leer mucho y hacer trabajos muy extensos. Además las rúbricas de los trabajos no especifican bien como se evalúa. Pasa más tiempo quejándose de los estudiantes que dando la clase. Habla de lo perfecto profe que es y los estudiantes siempre los malos.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'e22d6f22d034d8821cc8567f00c6d99ba367f54fa59e65ae778e64eb7b868893'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Borra los comentarios de mis profes ojo. La actitud pedante y el ego inflado no permiten identificar lo poco claro claro que es con las asignaciones, no sigue reglamento alguno y se saca rubricas a ultima hora. Tipos como este le bajan lo prestigioso al Tecnológico, lo peor que hay. (90 en el curso)'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa']::TEXT[], '2020-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'eaae98719081b1bff516a4ebb12e4cb08fcb9762aab10fc2f124cab0eebb4888'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Hay una diferencia entre ser directo y ser un asqueroso pedante, él no la conoce. Lo peor de todo es uqe al inicio del semestre siempre dice que son lo malos estudiantes los que le dejan malas reseñas, pero en este punto del semestre no lo soporto más.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'ff2a8a708ba6134a04f80ec55b1a9c835f97447747cfd93552e223cf21b6160b'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'El basuras le llamo. Borra las críticas que se le hace en esta página. Ni en su casa lo respetan. Un total hijo de ????.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-10-25T00:00:00+00:00'::TIMESTAMPTZ, '0ab21a29fbe28ccd48741d8dc8af77ee138193c73bc5450ad43ba642b0292f14'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '7b557fc26cd0b1059116ac98ff2f8d78e51ef1aec7b39e2c62b33487abab4bac'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'es un profe que le gusta lo que hace, pero es muy confuso explicando y cree siempre tener la razon. las clases largas, asistir es importante y las tareas no son muy dificiles.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'f06737e2b915b962a9e0ea35638158be4c8db04cac2fb426c50eab290a2d6ab4'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es un buen profesor, interesado en que los estudiantes aprendan, deja muchos trabajos en grupo, por lo que es obligatorio aprender a trabajar grupalmente. Si quiere pasar el curso fácil no matricule con él, si quiere aprender sin duda matricule con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'cda5159f8394d655ab33adacefde24b6fbb3d07d4631f106eaf5c1a4bec9983b'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Profesor interesado en que se lea y se aprendan habilidades para el ámbito profesional. Le gusta el orden en los trabajos. Para estudiantes de MATEC es bueno, pues proporciona metodologías de trabajo en equipo, importantes para el desenvolvimiento en el aula. No apto para gente mediocre. -Ariana RF.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-18T00:00:00+00:00'::TIMESTAMPTZ, '73478f6303f4a3c21d7525f2f0710bb01d581bbbf7f0d309053ff8d12693f5ac'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Buen profesor, sabe mucho acerca de la materia y de muchas áreas más y tiene un interés por que el estudiante aprenda, el trabajo en grupo es importante ya que el curso se basó principalmente en eso y él no regala notas se tiene que aprender para aprobar el curso'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'f3fe10dc28f4b14355b22b3090e7e8375fb73ccfea5b73b4baf46dd1eb7e995f'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Me parece un buen profesor, el cual no regala la nota. Le interesa que el alumno aprenda, si este pone atención y vela por que aprenda algo útil. Las clases son bastante normales para el tipo de materia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'bbaafdffe30d22e93edf68a9a1c22e4aac0728e5c4504f94f9c9619c2e9270d6'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Parece que le da pereza dar clase por lo que provoca que a los estudiantes también les dé pereza. No explica nada y si lo hace es con pocas ganas; se enfoca más en la investigación que en el curso. Es irrespetuoso. De los peores profes del TEC'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '4c8b6d28b3e4248c271721891b99293c1168ef7636fb0ea0ec6078bd8efbff5e'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Muy mal profesor. Sus clases se basan en quejarse ya sea del Tec o de la vida en general. Super irrespetuoso con los estudiantes. Si tiene la opción de no llevarlo con este profe, aproveche y busque otro profe.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '4ea1284d3725a971083d0aaca2ba44899440fa13346bdb7c9dc1c01d3f7efefa'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Un profesor que no sabe explicarse, le da tanto rodeo a las ideas que termina perdiendo lo, no lo recomiendo en lo absoluto'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-08-20T00:00:00+00:00'::TIMESTAMPTZ, '4e3d278aa2f2717970299ffaba3e2847fe75bb4ed9edcf97ba06ca47b309adb0'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'NO LO RECOMIENDO. En mis 4 años en el TEC es el PEOR profesor que he tenido. Sus calificaciones son totalmente SUBJETIVAS . Si usted le cae mal a él, de el curso por perdido. Juega de que sabe mucho pero es un completo farsante ya que él solo se contradice. Si es su única opción NO lo matricule!!'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e63da2ca45eae4ceacb4711cb4988db3b92bc175d874687eb9f2f38a90028e3e'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Uno de los profesores mas arrogantes que he concocido, le gusta hacer comentarios para hacerlo a uno sentirse mal, imparte la materia que se le antoje, es decir, nunca vimos nada el curso pero si sobre metodos de investigaión porque es lo único en la vida que a el le interesa.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'af1bb96007a2055a200e56559994fb3b34d3c942397d7326ecd65910b438afd4'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'No es difícil como muchos dicen, simplemente si hay que hacer uno que otro trabajo, pero las clases dan gusto.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-26T00:00:00+00:00'::TIMESTAMPTZ, 'db2949895727fb440913582d88d64e454fbe43e1df428723cb0075391cac2ded'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Hay que ponerle mucho. Si quiere pasar debe dedicarle demasiado tiempo. Vaya a consulta siempre.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e3162bc8cfacbc2371ac21ed995c7b34cb0e32091ad77860e49e37da710f1ad4'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'cómo se suda este curso, muy matados los trabajos para el curso que es, lo hace de 5 créditos, sin embargo valora el estudiante, intenta ser claro y no tenerle miedo es claro, es cuestión de hablar las cosas cómo son y de frente, además, que rico cuando uno pasa cursos con este tipo de profes'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '10606c8a23f552ab50c9be3f002e28c2d0f7b6fcf8bd3fee1700533cb573d22b'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'No recomiendo para nada este profe. Falté 3 veces en el curso, contaba con dos justificaciones válidas, sin embargo, el profe no me las quiso aceptar y hasta me dijo que dejara de ir a su clase porque ya estaba quedad por ausencias. Además, si se le pide retroalimentaciones no es claro.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-06-11T00:00:00+00:00'::TIMESTAMPTZ, '97f1e6f5ced496353a9e69938d2139f936e6b4f18bf5728f9e89d5791ecc6b33'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Muy estricto pero hace la clase muy interesante, ayuda al estudiante si se ve el interés'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-30T00:00:00+00:00'::TIMESTAMPTZ, '6f11a434919fecc16619749028312b15986a7579ab6197787c634211538690a5'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-04-13T00:00:00+00:00'::TIMESTAMPTZ, 'd0457cb493d03820c8e9d29d6f1f6d8a4538c52f7af97d9773dce5cb8042d1c5'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2018-04-12T00:00:00+00:00'::TIMESTAMPTZ, '2c546d33f09c5877db7da82fc8e81d0d866c6abc63f17930926b2f43013f5f5a'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Wilmer es el peor profesor que he tenido en toda mi vida estudiantil. No es duro para calificar y es una persona con una forma de pensar interesante, pero todo eso se queda opacado por la desorganización y falta de humildad que tiene. No es recomendable, aunque el curso se pasa.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-22T00:00:00+00:00'::TIMESTAMPTZ, '408bac667074d80f74e4fa77247631031fc8d187d6fbdb066ef10eabb776771c'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Las clases son largas y aburridas. De materia solo da 30 min, el resto se pasa contando historias. Deja muchos trabajos.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2017-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'e093796f469f29c11ed42a3c96147e8412d0a9f947b832836530b7f8057902c9'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Profesor con mucho conocimiento y muchos títulos, pero no sabe dar una clase realmente su punto de vista es muy cerrado y no permite básicamente que se le cuestione dicha forma de pensar, no da ayuda al que lo necesita solo le dice que vuelva a empezar. carece de moral y ética'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'df94df6381397ce7087a132c57a896c6490467aa310c3a8a5b9ea31c1724aac0'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Juega de lo que no es, en algunos trabajos no deja instrucciones claras, aunque esto se complementa con que no califica muy duro, solo no hay que hacer caballadas en los bretes'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '79eccac116fa6aae91a4b523ef10c4ef430818d33efea1193ece0cf129b642b3'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Tiene fama de que es mal profe pero en realidad es muy bueno. Es bastante claro y las instrucciones de las evaluaciones son sencillas.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'fef8398e240fd5f7910cd9637ee67d43c3180a68b3e23501479bd101a52b816d'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Sabe mucho pero no esperen la mínima muestra de empatía de su parte. Llevar el curso con el no es tan malo como dicen, deja muchos trabajos pero algunos son bastante cortos.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-11-17T00:00:00+00:00'::TIMESTAMPTZ, '84b1b6339a4197f177271321c75ea2b0efab4fcd0bd38df62fd56b5ef4ab12a8'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Profesor que sabe mucho de lo que habla, pero su humildad queda por el suelo. Sus clases se basan en intimidar al estudiante.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-09-22T00:00:00+00:00'::TIMESTAMPTZ, 'e694de09f0f5f08cdb14997db07f8dcb10e4970f5d163ec0683c4c495b7742f7'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es una persona muy preparada que se preocupa porque uno realmente aprenda, una vez que lo sabe tratar se hace muy llevadero el curso, ya que brinda ayuda en sus horas de consulta'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'fd12bf6c961d2430b2fad90407e3927f47b934b6b28041bb640909db9423b525'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es el peor profesor. No matricule con él, ni aunque sea la última opción. Deja trabajos sumamente largos y difíciles. Piensa que es el único curso que uno tiene.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '4d448becba6b4835433c74aec62f32c9f72b4515a5345dab3aff5027c059dbd1'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Sabe bastante, Muchísimo trabajo, no recomendado si le falta tiempo. Trabajos largos, complicados y constantes. Intenta intimidar al estudiante constantemente, ASISTENCIA OBLIGATORIA. Califica más suave de lo que parece, lo realmente duro es aguantar al profe y lo desgraciado que se torna.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1c1b42261de772e3b0f4e0ec2d96681bd78a1654e6954b545aef99e8b9d51281'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es un profe bastante duro, tiene que ir a clase sino ya perdió el curso, trata de intimidar al estudiante con tal de crear miedo, pero al final es pura hablada.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0fe80fa641485e922690a7748dba59ab89163c6f436655f58455f12d3a92610c'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'El curso se convierte en un curso de 4 creditos por la cantidad y dificultad de los trabajos. En mi opinión el profe es muy intimidante para el estudiante y mas si uno no es bueno exponiendo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'ec860b17a92fdd0109c2f7dc03fc837cfbe60bd7b14632c4232b36e4ec2079fe'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Estricto, y por eso dicen que es un dolor. Pero es buen profe, solo hay que cumplir con todo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, '33f60c08cbacaf88b0cd8c03273831a1c87a79ca615d723b008c9643d9038414'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Es un gran profesor, sabe mucho, aunque si califica durillo, se hace un desmadre con los trabajos y fechas que pone y le intenta meter mas miedo del usual al estudiante, pero se puede pasar y con notas de 80 o 90 pero hay que ponerle y no abandonar el curso.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '2a949ef8e6960a3cfd22478c93248fd101329202ebb2fc1a14f9736d45744d9f'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Quiere que los trabajos sean tesis, es arrogante, debe tener tiempo para llevarlo con el'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, '0ae0f48f9e793c8a55afd30a44a7f4004c74d1c07225e0b1c92c804b23f623c9'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Un poco desordenado con respecto a las fechas de tareas o proyectos, estar atento a eso. Hay que ponerle mucho, a veces piensa que es el único curso que uno lleva.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-07T00:00:00+00:00'::TIMESTAMPTZ, '1b6a0d981393cf7fd5d735e625543c77ad1bd243beb3aceee4dfc6238ce0a791'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Toma el curso como si fuera el único que uno está llevando, tiene mucho enredo con fechas y las instrucciones de los trabajos no son claras'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2017-04-06T00:00:00+00:00'::TIMESTAMPTZ, 'd0c46cc40c201ebb1bed6bdf5e4517c909cdd4966f219f4f9b55f9f5f20a6afe'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Necesita dos cosas si va a llevar el curso con él: 1. Trabaje, dé su mayor esfuerzo en cada una de las entregas. 2. Aprenda a investigar, deje el "copy & paste" en el cole, si usted quiere hacer un buen proyecto no cometa plagio.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '2c60c490eb2f87580ad083858c8cf20f0656a83f6a903bd526cd7a79fe51eb8d'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'participar es importante, califica de una manera estricta, es muy directo y eso a veces intimida, hace la clase llamativa es un profe que de verdad sabe lo que hace pues el hace investigaciones con cierta regularidad por lo que exige eso en los trabajos que deja y no es claro en las instrucciones.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2016-11-09T00:00:00+00:00'::TIMESTAMPTZ, '290e3c631d4740f1536eaf377b7b6f4778e69cb5af585a8dad20c2f087a11180'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Habla más de la cuenta'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2016-08-31T00:00:00+00:00'::TIMESTAMPTZ, '36a24814046156329521f6f8c5bac201cba125114f27a99601b60ae82638b8a6'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Si no es crítico y no le gusta hablar en frente de la clase no llevar este curso con él. Es muy pasable, pero hay que ganarse la nota. Lo recomiendo si realmente quiere aprender de filosofía porque el mae es un crack. Deja muchos trabajos al principio, pero se sale en semana 15. No califica muy duro'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9996840204a5ed4a765b444e8eadcc176de30fe800176be3bff729a813316fa4'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Muy exigente, hay que participar sí o sí. Explica muy bien y hace la clase entretenida pero es muy duro para calificar. Hay que esforzarse mucho para pasar.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'eca307f1e31f8b5e0a51f2e7c00c2bcb07a297e3b8d3666e4ca61737f845b78a'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Debe participar en clase'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '1d10c60bbd6c15e236c6af2d5c98b5ed89410a2124b722329f9dde4cac91ad28'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Buen profe. Si Ud es vago no pasa el curso. Deja muchor trabajos y muy largos'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2016-03-22T00:00:00+00:00'::TIMESTAMPTZ, '8c1b49a2f530d7a6b91ac6c8839632703783e2fc9cc36ee01e88de7e4fb3c51b'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Si a uno le gusta hablar y es bueno para expresar sus ideas es una buena opción de buen profesor, si uno es tímido casi que es imposible pasar el curso.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2016-03-17T00:00:00+00:00'::TIMESTAMPTZ, '18184a079edebd327ef2ba668276ca99c51b051399673dbddac66b5ce2d8a754'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'El mejor profesor de ciencias sociales, es un gran profesional. Siempre se interesa en los estudiantes, en la enseñanza y aprendizaje. Se aprende exponencialmente, vale la pena matricular con él. No me resultó nada sencillo al principio, pero valió la pena al final. Comprométase con el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-25T00:00:00+00:00'::TIMESTAMPTZ, '960a4ced70962a698c2af9f6eae2d734ba326e886fbdddce36d688c80b83718d'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Si quiere aprender, esta es de las mejores opciones para seminario de ética, realmente enseña academia este profesor'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '25da71d065f1233f9b320b879795b93f1fe97c97bf446de35b167b8b70d54767'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Busca forma criterio en lo estudiantes , a veces asusta, pero nada del otro mundo , solo hay que tratar de hacer la cosas buen'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'f18e8b1c31f98a94339bdb0d89d113775665109a8dafd096be153aac80098e2c'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Excelente profe, el conocimiento que transmite y que tiene es increíble! Es duro pero yo creo que al final vale la pena, si usted es de esos que se queja por los profes duros mejor ni meta con el. Si es analítico y crítico no lo piense!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-24T00:00:00+00:00'::TIMESTAMPTZ, 'f517997964090531298fa7b2c936bba19a0e102a576b7bd869e864577a62134a'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Excelente profesor, lo recomiendo a quienes quieran aprender, de lo contrario ni se les ocurra.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '083df03b733a5c7570bea11ef869f8d178e198eb784b3789fb46db4ad17d27f0'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'c2422dd7e44dec157aa9e580208b57d5ab2f3212d95be484e41e91b800dc8557'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Èl profe es bueno, pero si la agarro contra usted por lo que sea, aunque usted no haya hecho nada malo, ya perdio el curso.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '514183fe2235ca27c9e95a23ffb29b6d987386f46d094d39d2f5d63a0a659c25'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Es un profesor excelente, si usted va a un curso con el va a APRENDER, sinceramente los trabajos son duros pero el califica justo, y una clase con el es lo mas interesante, pueden ser 3 horas escuchandolo hablar que usted no se aburrira.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '9b1669dc55da6fa1d664ea24ab254f8a97003cabb62171b39b6f38ad611c272c'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (129::BIGINT, 'Con este profe el secreto es ir a preguntarle como quiere las cosas y pensar antes de hablar!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'dbf9f21861c5efad5994dc7fb0f7380ba3291a2b193fa14cc88adb71e4d710a1'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'bd4fe393beb6a8794d4bcb3a28eceb578da964cfda4fc4b48e58b3274aec5d70'::TEXT, ARRAY[981]::BIGINT[]),
    (129::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'f6f8a4fc7557412c707b1da86f5b7956e44720c925b4d518ea8af74aeba83806'::TEXT, ARRAY[980, 981, 2460]::BIGINT[]),
    (129::BIGINT, 'Sabe mucho y es muy bueno transmitiendo las ideas, se pasa bien el rato, es de mente muy abierta entonces le gusta cuestionar temas interesantes pero mantiene el respeto, a veces hay que tomar a la ligera ciertos comentarios que haga, lo malo es que deja demasiados trabajos..'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '051dd3132c85b22fcbef8e12c96ebbc0637ec08a3c8db18ae3d341f4e7fa5bf0'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'Le gusta hacer comentarios sarcásticos sin importar la opinión o creencias de los demás. Es ateo y lo pregona,así que si es religioso mejor no matricule con él. Calificando es muy justo. Exige mucho'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'bc84a10ed4d8e11af804831f7d991400a926719b7b4d89471f7adbf149c0d6c3'::TEXT, ARRAY[980]::BIGINT[]),
    (129::BIGINT, 'se burla de los estudiantes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '0f8f19bfe74fad116e5d4bbf0f165ea99d79944c3bf4c1136cb3ac66d7f80abd'::TEXT, ARRAY[559]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
